//! Property tests that the loader always returns.

mod support;

use openmpt_ext::Module;
use proptest::collection::vec;
use proptest::prelude::any;
use proptest::prelude::prop;
use proptest::prelude::prop_assert;
use proptest::proptest;
use proptest::test_runner::Config;

/// Applies generated byte changes to a valid file, so the bytes reach the MOD
/// reader.
///
/// Each pair is a selector and a value. The selector picks the byte index, so
/// proptest shrinks a failing case toward the first bytes of the file.
fn mutate_mod(bytes: &[u8], mutations: &[(u8, u8)]) -> Vec<u8> {
    let mut out = bytes.to_vec();
    for (selector, value) in mutations {
        let index = usize::from(*selector) % out.len().max(1);
        if let Some(byte) = out.get_mut(index) {
            *byte = *value;
        }
    }
    out
}

fn config() -> Config {
    Config {
        cases: 256,
        ..Config::default()
    }
}

proptest! {
    #![proptest_config(config())]

    #[test]
    fn from_bytes_never_crashes(bytes in vec(any::<u8>(), 0..8192)) {
        // A load either succeeds or fails. A crash, a hang, or an unwind
        // fails the test.
        let module = match Module::from_bytes(&bytes, &[]) {
            Ok(module) => module,
            Err(error) => {
                prop_assert!(!error.message.is_empty());
                return Ok(());
            }
        };
        prop_assert!(module.num_channels() >= 0);
    }

    #[test]
    fn mutated_mod_never_crashes(mutations in vec((any::<u8>(), any::<u8>()), 0..17)) {
        let bytes = support::simple_mod();
        let mutated = mutate_mod(&bytes, &mutations);
        let module = match Module::from_bytes(&mutated, &[]) {
            Ok(module) => module,
            Err(error) => {
                prop_assert!(!error.message.is_empty());
                return Ok(());
            }
        };
        prop_assert!(module.num_channels() >= 0);
    }

    #[test]
    fn an_empty_load_fails(empty in prop::collection::vec(any::<u8>(), 0)) {
        let result = Module::from_bytes(&empty, &[]);
        prop_assert!(result.is_err());
    }
}
